			function setCmbInstFilter() {
			    var cmb1 = app.lookup("cmb1").value;
			    var voDsOperInst = app.lookup("dsInst");
			    if (cmb1 == '') {
			        voDsOperInst.forEachOfUnfilteredRows(function(row) {
			            row.setValue("FILTER", 'N');
			        });
			    } else {
			        voDsOperInst.forEachOfUnfilteredRows(function(row) {
			            var filter = false;
			            var bizYrArr = row.getValue("BIZ_YR").split('|');
			            
			            for (var idx = 1; idx < bizYrArr.length; idx++) {
			                var bizYr = bizYrArr[idx];
			                if (bizYr == cmb1 || cmb1 == '')
			                    filter = true;
			            }
			            
			            if (filter)
			                
			                row.setValue("FILTER", 'Y');
			            else
			                row.setValue("FILTER", 'N');
			        });
			    }
			    
			    var cmb2 = app.lookup("cmb2");
			    
			    if (cmb2.getItemCount() == 2)
			        cmb2.selectItem(1);
			    else if (!cmb2.findItem({
			            value: cmb2.value
			        }))
			        cmb2.selectItem(0);
			}
